// Minimal interactive sprite demonstration: fire toggles its colour.
// Uses an existing sprite bitmap at $3000, generated by this program.
int main()
{
    unsigned char joy = 0;
    __c64_poke(0x3000, 255);
    __c64_poke(0x3001, 255);
    __c64_poke(0x3002, 255);
    __c64_poke(0x07F8, 192);
    __c64_poke(0xD000, 120);
    __c64_poke(0xD001, 100);
    __c64_poke(0xD015, 1);
    while (1)
    {
        joy = __joystick2();
        if (joy >= 16) __c64_poke(0xD027, 2);
        else __c64_poke(0xD027, 1);
    }
    return 0;
}
